"""Small login function used by the coding-agent demo."""

from config import DEMO_PASSWORD, DEMO_USERNAME


def login(username: str, password: str) -> bool:
    """Accept only the exact example credentials; empty input is rejected."""
    if not username or not password:
        return False
    return username == DEMO_USERNAME and password == DEMO_PASSWORD


def login_result(username: str, password: str) -> dict[str, bool]:
    """Return only authentication status, never credentials."""
    return {"authenticated": login(username, password)}

import pytest
from login import login_result

@pytest.mark.parametrize("username,password,expected", [
    ("demo", "demo-only", True), ("demo", "wrong", False),
    ("", "demo-only", False), ("unknown", "demo-only", False),
])
def test_login_result_contains_only_status(username, password, expected):
    result = login_result(username, password)
    assert result == {"authenticated": expected}
    assert set(result) == {"authenticated"}
    assert password not in repr(result)
